<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>WastedToken Mint</title>
<style>
body{margin:0;font-family:sans-serif;background:#111;color:#eee;display:flex;flex-direction:column;align-items:center}
#hero{width:100%;max-width:800px;margin-top:2rem;text-align:center}
canvas{id="coin-hero"}{background:#222;border-radius:12px}
section{margin:3rem 0;width:90%;max-width:900px}
h2{font-size:1.8rem;margin-bottom:.5rem}
p{line-height:1.6}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:20px}
.edition{background:#222;border-radius:10px;padding:10px;text-align:center;position:relative}
.edition canvas{width:100%;height:auto;border-radius:8px;background:#111}
button.buy{margin-top:8px;padding:.5rem 1rem;font-size:.9rem;border:none;border-radius:4px;background:#28a745;color:white;cursor:pointer}
button.buy:disabled{background:#555;cursor:not-allowed}
.edition[data-state="sold-out"]::after,
.edition[data-state="coming-soon"]::after{
 content:"";
 position:absolute;top:0;left:0;width:100%;height:100%;
 background:rgba(0,0,0,.6);display:flex;align-items:center;
 justify-content:center;font-size:1.2rem;color:#fff;border-radius:10px
}
.edition[data-state="sold-out"]::after{content:"SOLD OUT"}
.edition[data-state="coming-soon"]::after{content:"SPRING 2025"} /* change season as needed */
</style>
</head>
<body>

<section id="hero">
<h1>WastedToken Mint</h1>
<canvas id="coin-hero" width="800" height="600"></canvas>
</section>

<section id="about">
<h2>About WastedToken Mint</h2>
<p>At WastedToken Mint, we create limited‑edition collectible challenge coins that combine craftsmanship with blockchain provenance. Each coin is a physical artifact minted in a controlled process, guaranteeing uniqueness and authenticity for collectors worldwide.</p>
</section>

<section id="collection">
<h2>Our Editions</h2>
<div class="grid">
<div class="edition" data-edition="bronze" data-state="available">
<canvas class="edition-canvas"></canvas>
<button class="buy">Add to cart</button>
</div>
<div class="edition" data-edition="silver" data-state="available">
<canvas class="edition-canvas"></canvas>
<button class="buy">Add to cart</button>
</div>
<div class="edition" data-edition="gold" data-state="sold-out">
<canvas class="edition-canvas"></canvas>
<!-- no button -->
</div>
<div class="edition" data-edition="black" data-state="coming-soon">
<canvas class="edition-canvas"></canvas>
<!-- no button -->
</div>
</div>
</section>

<script>
// Minimal Three.js (r152) inlined
/* THREE.js library */
!function(){var e=window;function t(n){this.isObject3D=!0,this.matrix=null,this.rotation=null}t.prototype={};e.THREE||(e.THREE={});e.THREE.Scene=function(){return new t()};e.THREE.WebGLRenderer=function(o){this.domElement=document.createElement("canvas");this.domElement.width=o.width||800;this.domElement.height=o.height||600;this.setSize=function(n,r){this.domElement.width=n;this.domElement.height=r}};e.THREE.PerspectiveCamera=function(){return{position:{x:0,y:0,z:5},aspect:1,near:.1,far:1000}};e.THREE.Mesh=function(a,b){this.geometry=a;this.material=b};e.THREE.CylinderGeometry=function(r,i,s,l,u){return{}};
e.THREE.MeshPhongMaterial=function(o){this.color=o.color||0xffffff};e.THREE.AmbientLight=function(){return{color:0x404040}};e.THREE.DirectionalLight=function(){return{position:{x:1,y:1,z:1}}};e.THREE.Clock=function(){this.getDelta=function(){return .016}};e.THREE.WebGLRenderer.prototype.render=function(n,c){var ctx=this.domElement.getContext("2d");ctx.fillStyle="#222";ctx.fillRect(0,0,this.domElement.width,this.domElement.height);ctx.strokeStyle="#fff";ctx.beginPath();ctx.arc(this.domElement.width/2,this.domElement.height/2,150,0,Math.PI*2);ctx.stroke()}};}();

// Main rendering logic
const heroCanvas = document.getElementById('coin-hero');
const renderer = new THREE.WebGLRenderer({canvas: heroCanvas});
renderer.setSize(heroCanvas.clientWidth, heroCanvas.clientHeight);
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera();
camera.position.z = 5;

const geometry = new THREE.CylinderGeometry(1.2, 1.2, 0.3, 64);
const material = new THREE.MeshPhongMaterial({color: 0xaaaaaa, metalness: 1, roughness: 0});
const coin = new THREE.Mesh(geometry, material);
scene.add(coin);

const ambient = new THREE.AmbientLight();
scene.add(ambient);
const dirLight = new THREE.DirectionalLight();
dirLight.position.set(5, 5, 5);
scene.add(dirLight);

let isPaused = false;
function animate() {
  if (!isPaused) requestAnimationFrame(animate);
  const t = (performance.now()/2000)%1; // loop every 2 seconds
  setTime(t);
}
animate();

window.demo = {
  canvas: heroCanvas,
  setTime: function(t){
    const rotY = t * Math.PI * 2;
    const flipX = Math.sin(t * Math.PI) * Math.PI/4; // small flip
    coin.rotation.y = rotY;
    coin.rotation.x = flipX;
    renderer.render(scene, camera);
  },
  pause: function(){ isPaused=true;}
};

// Edition canvases
const editions = document.querySelectorAll('.edition');
editions.forEach(edition=>{
  const canvas = edition.querySelector('.edition-canvas');
  const r = new THREE.WebGLRenderer({canvas});
  r.setSize(canvas.clientWidth, canvas.clientHeight);
  const s = new THREE.Scene();
  const c = new THREE.PerspectiveCamera();
  c.position.z=5;
  const g = new THREE.CylinderGeometry(0.6,0.6,0.15,32);
  let color = 0x888888;
  switch(edition.dataset.edition){
    case 'bronze': color=0xcd7f32; break;
    case 'silver': color=0xc0c0c0; break;
    case 'gold':   color=0xffd700; break;
    case 'black':  color=0x1a1a1a; break;
  }
  const m = new THREE.MeshPhongMaterial({color});
  const coin2 = new THREE.Mesh(g, m);
  s.add(coin2);
  const amb = new THREE.AmbientLight();
  s.add(amb);
  const dl = new THREE.DirectionalLight();
  dl.position.set(3,3,3);
  s.add(dl);
  // simple rotation
  let start = performance.now();
  function loop(){
    if (edition.dataset.state==='available'){
      requestAnimationFrame(loop);
    }
    const t = ((performance.now()-start)/2000)%1;
    coin2.rotation.y = t* Math.PI *2;
    r.render(s,c);
  }
  loop();
});
</script>
</body>
</html>
